import{_ as d,C as t,o as c,c as p,j as a,a as h,G as r,a2 as s}from"./chunks/framework.BgSoyxN5.js";const T=JSON.parse('{"title":"TickerForge Partner Requirements | Who Qualifies, What Partners Commit To, When Access Ends","description":"Eligibility rules, posting commitments, disclosure duties, and the exact conditions under which TickerForge partner access is paused or ends. Read this before applying for a partner pilot.","frontmatter":{"title":"TickerForge Partner Requirements | Who Qualifies, What Partners Commit To, When Access Ends","description":"Eligibility rules, posting commitments, disclosure duties, and the exact conditions under which TickerForge partner access is paused or ends. Read this before applying for a partner pilot.","aside":false,"locale":"en","alternateLocales":{"en":"/partners/requirements","ru":"/ru/partners/requirements"},"pageClass":"partners-page"},"headers":[],"relativePath":"partners/requirements.md","filePath":"partners/requirements.md","lastUpdated":1788362384000}'),u={name:"partners/requirements.md"},g={class:"partners-wide"};function m(f,e,b,w,y,v){const n=t("PartnerPageAnalytics"),i=t("PartnerCabinetCta"),o=t("PartnerReferralCta"),l=t("PartnerLeadForm");return c(),p("div",null,[e[0]||(e[0]=a("h1",{id:"partner-requirements",tabindex:"-1"},[h("Partner Requirements "),a("a",{class:"header-anchor",href:"#partner-requirements","aria-label":'Permalink to "Partner Requirements"'},"​")],-1)),e[1]||(e[1]=a("p",null,"Who can become a TickerForge partner, what a partner commits to, and when partner access ends.",-1)),e[2]||(e[2]=a("p",null,"The partner program is an exchange, not a giveaway. This page states both sides of it in plain terms so nobody has to guess: what we give, what we ask, and what causes access to stop.",-1)),r(n,{offer:"requirements",locale:"en"}),e[3]||(e[3]=s('<div class="partners-hero-actions"><a class="partners-button partners-button--primary" href="#apply" data-partner-event="cta" data-partner-option="propose_pilot" data-analytics-placement="partner_hero">Apply For A Pilot</a><a class="partners-button partners-button--secondary" href="#access-ends" data-partner-event="cta" data-partner-option="access_rules" data-analytics-placement="partner_hero">When Access Ends</a></div><p class="partners-locale-switch"><a href="/ru/partners/requirements" hreflang="ru" data-partner-event="cta" data-partner-option="locale_ru" data-analytics-placement="partner_locale_switch">Читать эту страницу на русском</a></p><p class="partners-backlink"><a href="/partners">Back to all partner options</a> · <a href="/partners/what-you-get">What we give</a> · <a href="/partners/stock-analysis-and-ideas">Telegram research</a> · <a href="/partners/market-news">Market news</a> · <a href="/partners/portfolio-health">Portfolio health</a> · <a href="/partners/cabinet">Partner Cabinet</a></p><p>This page is about eligibility and the access lifecycle. The content formats in each direction are listed on the three program pages.</p><p>TickerForge is educational decision-support software. It is not financial advice, a signal channel, a broker, or a promise of investment results.</p><h2 id="benefits" tabindex="-1">🎁 What A Partner Gets <a class="header-anchor" href="#benefits" aria-label="Permalink to &quot;🎁 What A Partner Gets {#benefits}&quot;">​</a></h2><p>The same benefits the Partner Program hub shows inside the Telegram bot. <a href="/partners/what-you-get">What we give a partner</a> is the full version of this list — product access, content, tracking, reporting and how referral rewards are calculated.</p><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>⭐ Standard access.</strong> TickerForge Standard for the whole pilot window, so posts are built from the full research layer instead of the free public preview.</li><li><strong>🧠 Ready-to-post research.</strong> Live Stock Verdict, Insider Activity, Fund Moves, and Market Regime content you can quote inside your own posts.</li><li><strong>🔗 Tracked links.</strong> Every partner post can send readers straight into the matching TickerForge workflow through a tracked Telegram deep link.</li><li><strong>💰 Referral earnings.</strong> Readers attributed through your partner links join the existing TickerForge referral program and earn under the same rules as <a href="/ambassador">/ambassador</a>.</li><li><strong>📊 Measurable results.</strong> Generated posts, tracked clicks, referrals, and estimated earnings in your Partner Cabinet inside the bot.</li></ul></div><h2 id="eligibility" tabindex="-1">Who Can Become A Partner <a class="header-anchor" href="#eligibility" aria-label="Permalink to &quot;Who Can Become A Partner {#eligibility}&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Audience size:</strong> from 1,000 real subscribers or followers on the main channel you plan to post in — Telegram channel, YouTube, Instagram, LinkedIn group or page, newsletter, Discord, or forum community.</li><li><strong>Real audience:</strong> organic subscribers. Bought followers, engagement pods, and bot-inflated view counts do not qualify, and are grounds for ending a pilot at any point.</li><li><strong>Topic fit:</strong> the channel is about investing, markets, personal finance, or company analysis. TickerForge content has to fit what your audience already reads.</li><li><strong>Live channel:</strong> at least 3 months of history and a regular posting rhythm — roughly 2 or more of your own posts per month.</li><li><strong>Language:</strong> English or Russian audiences are supported today. Other languages are considered case by case.</li><li><strong>Telegram account:</strong> approval binds the partner seat to one Telegram account, so you need to be reachable in Telegram even if your channel lives elsewhere.</li><li><strong>Compliance fit:</strong> the channel does not provide trading signals, promise returns, run copy-trading, or market itself with profit guarantees.</li></ul></div><p><strong>Smaller audiences.</strong> The 1,000 threshold is a default, not a wall. A 300-member closed investor club, a consultant with a real client base, or a niche newsletter with high open rates can be approved case by case. Tell us the engagement numbers, not only the subscriber count.</p><h2 id="commitments" tabindex="-1">What A Partner Commits To <a class="header-anchor" href="#commitments" aria-label="Permalink to &quot;What A Partner Commits To {#commitments}&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Posting volume:</strong> the standard pilot is 3 qualified posts inside a 30-day access window. Both numbers are set per partner at approval and are visible in your Partner Cabinet as <em>Required posts</em>.</li><li><strong>Ongoing cadence:</strong> if the pilot continues, the usual rhythm is 2-4 qualified posts per month.</li><li><strong>Only verified posts count.</strong> The Cabinet shows generated posts and verified posts separately. Generating a post in the bot is not the same as publishing it: only published posts that we can verify count toward the requirement.</li><li><strong>Disclosure:</strong> if a post is sponsored, affiliate-supported, or materially helped by complimentary partner access, say so in a way that fits your channel.</li><li><strong>Personal seat:</strong> the access seat belongs to the approved partner. It is not transferable, not a team account, and must not be shared with your audience or resold.</li><li><strong>Data use:</strong> TickerForge output is for your own posts. Republishing it as a standalone feed, database, or competing product is not part of the program.</li><li><strong>Wording:</strong> keep partner posts on the educational side — market context and evidence, not personal recommendations or return promises. The rules are the same ones TickerForge follows in its own content.</li></ul></div><h3 id="what-counts-as-a-qualified-post" tabindex="-1">What Counts As A Qualified Post <a class="header-anchor" href="#what-counts-as-a-qualified-post" aria-label="Permalink to &quot;What Counts As A Qualified Post&quot;">​</a></h3><p>A post counts when all four are true:</p><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li>it contains a <strong>real TickerForge check</strong> — an actual evidence block, screenshot, or diagnostic you ran, not a paraphrase;</li><li>it keeps <strong>your own voice and analysis</strong> — a bare screenshot with no commentary is not a partner post;</li><li>it carries a <strong>clear educational disclaimer</strong>;</li><li>it links to a <strong>tracked bot or product link</strong> so the result can be measured.</li></ul></div><h2 id="lifecycle" tabindex="-1">How Partner Status Moves <a class="header-anchor" href="#lifecycle" aria-label="Permalink to &quot;How Partner Status Moves {#lifecycle}&quot;">​</a></h2><div class="partners-wide partners-wide--timeline"><div class="partners-steps"><div><span>1</span><strong>Lead</strong><p>You send the form. Nothing is granted yet.</p></div><div><span>2</span><strong>Under review</strong><p>We check the channel, audience, topic fit, and pilot idea.</p></div><div><span>3</span><strong>Active</strong><p>Standard access is granted for the agreed window and the Cabinet opens.</p></div><div><span>4</span><strong>Paused</strong><p>Access stops immediately, by either side, and can be reactivated later.</p></div><div><span>5</span><strong>Expired</strong><p>The window ended. Access can be extended or renewed after a review.</p></div></div></div><p>Partner access is time-limited by design and does not renew automatically. Continuation is a decision, and it is based on what the pilot actually produced.</p>',19)),r(i,{locale:"en"}),e[4]||(e[4]=s('<h2 id="access-ends" tabindex="-1">When Partner Access Is Paused Or Removed <a class="header-anchor" href="#access-ends" aria-label="Permalink to &quot;When Partner Access Is Paused Or Removed {#access-ends}&quot;">​</a></h2><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>The window ends.</strong> The access period runs out and is not extended.</li><li><strong>The cadence stops.</strong> The agreed number of verified posts is not published during the window, or the ongoing monthly rhythm stops.</li><li><strong>Posts do not qualify.</strong> Publications skip the real check, the disclaimer, or the tracked link, so nothing can be verified or measured.</li><li><strong>The seat is shared.</strong> Access is passed to another person, used as a team or client account, resold, or handed to the audience.</li><li><strong>The audience is not what it looked like.</strong> Subscriber counts or engagement turn out to be bought or artificially inflated.</li><li><strong>The framing breaks the rules.</strong> TickerForge is presented as a signal service, a profit guarantee, a trading robot, or personalized advice.</li><li><strong>Product data is redistributed.</strong> Output is republished as a standalone feed, database, or competing product.</li><li><strong>Spam or fraud.</strong> Mass unsolicited posting, fake traffic to tracked links, or self-clicking to inflate pilot metrics.</li><li><strong>You want to stop.</strong> A partner can end a pilot at any time, with no penalty and no obligation to explain.</li></ul></div><p>For anything except abuse, the normal path is a conversation first: we ask what happened, and pause only if the cadence genuinely stopped. A pause is reversible — a paused or expired partner can be reactivated later without reapplying from scratch.</p><h3 id="what-happens-to-your-referrals" tabindex="-1">What Happens To Your Referrals <a class="header-anchor" href="#what-happens-to-your-referrals" aria-label="Permalink to &quot;What Happens To Your Referrals&quot;">​</a></h3><p>Partner access and referral earnings are separate things, and losing one does not erase the other.</p><div class="partners-wide partners-wide--compact"><ul class="partners-feature-list"><li><strong>Readers already attributed to you stay yours.</strong> Referral ownership is first-touch and permanent: it is not reassigned when a pilot ends, and those referrals keep earning under the standard <a href="/ambassador">Ambassador</a> rules.</li><li><strong>New attribution stops.</strong> While partner access is not live, clicks on partner links no longer create new referral ownership.</li><li><strong>First touch wins.</strong> A reader who already belongs to another ambassador is never re-attributed to a partner link.</li></ul></div>',6)),r(o),e[5]||(e[5]=s('<h2 id="not-included" tabindex="-1">What Is Not Included Automatically <a class="header-anchor" href="#not-included" aria-label="Permalink to &quot;What Is Not Included Automatically {#not-included}&quot;">​</a></h2><div class="partners-wide partners-wide--not"><p>An approved pilot grants Standard access and nothing beyond it. These are separate commercial discussions:</p><ul><li>Pro-level access</li><li>bulk API or raw data feeds</li><li>custom or white-label reports</li><li>co-branded landing pages</li><li>paid placements and sponsorship budgets</li><li>exclusivity in a niche or language</li></ul><p>All of these can be discussed after a first measured pilot, and some of them are easier to justify once real numbers exist.</p></div><h2 id="apply" tabindex="-1">Apply For A Partner Pilot <a class="header-anchor" href="#apply" aria-label="Permalink to &quot;Apply For A Partner Pilot {#apply}&quot;">​</a></h2><p>Tell us about the channel and the pilot you want to run. The more of this you include, the faster the review: channel or community link, audience size and typical post reach, language, main topic, which partner direction you want, your first post idea, and whether you also want to discuss sponsored or affiliate terms.</p>',4)),a("div",g,[r(l,{source:"partners_requirements"})]),e[6]||(e[6]=s('<h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/partners">All partner options</a></li><li><a href="/partners/what-you-get">What we give a partner</a></li><li><a href="/partners/cabinet">How Partner Cabinet works</a></li><li><a href="/partners/stock-analysis-and-ideas">Telegram research partners</a></li><li><a href="/partners/market-news">Market news partners</a></li><li><a href="/partners/portfolio-health">Portfolio health partners</a></li><li><a href="/ambassador">Ambassador / referral program</a></li><li><a href="/pricing">TickerForge Pricing</a></li></ul>',2))])}const P=d(u,[["render",m]]);export{T as __pageData,P as default};
